pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public {
        c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this));
        c.rely(address(this));
    }

    function testFuzz_property(uint128 price) public {
        uint256 warpTimestamp = uint256(price) == 0 ? 1 : 0;
        vm.warp(warpTimestamp);

        c.updatePrice(price);

        assertTrue(c.latestPrice() == price);
    }
}
